/* Runaldinho service worker — generated by the publish script.
 *
 * Hashed assets are immutable, so they are cached first and never revalidated.
 * Navigations go to the network first: a new deploy must win, and the cached
 * shell only answers when the network is gone. Every publish ships a new
 * VERSION, and activating drops the caches of the previous one, so a client
 * never pairs a stale shell with chunks the host no longer serves.
 */
var VERSION = "mwezalzl";
var SCOPE = "/runaldinho/";
var SHELL_CACHE = "runaldinho-shell-" + VERSION;
var ASSET_CACHE = "runaldinho-assets-" + VERSION;
var SHELL = SCOPE + "index.html";

self.addEventListener("install", function (event) {
  event.waitUntil(
    caches
      .open(SHELL_CACHE)
      .then(function (cache) {
        return cache.add(new Request(SHELL, { cache: "reload" }));
      })
      .then(function () {
        return self.skipWaiting();
      }),
  );
});

self.addEventListener("activate", function (event) {
  event.waitUntil(
    caches
      .keys()
      .then(function (keys) {
        return Promise.all(
          keys.map(function (key) {
            if (key === SHELL_CACHE || key === ASSET_CACHE) return undefined;
            return caches.delete(key);
          }),
        );
      })
      .then(function () {
        return self.clients.claim();
      }),
  );
});

function cacheFirst(request) {
  return caches.open(ASSET_CACHE).then(function (cache) {
    return cache.match(request).then(function (hit) {
      if (hit) return hit;
      return fetch(request).then(function (response) {
        if (response.ok) cache.put(request, response.clone());
        return response;
      });
    });
  });
}

function networkFirstShell(request) {
  return caches.open(SHELL_CACHE).then(function (cache) {
    return fetch(request)
      .then(function (response) {
        if (response.ok) cache.put(SHELL, response.clone());
        return response;
      })
      .catch(function () {
        return cache.match(SHELL).then(function (hit) {
          if (hit) return hit;
          throw new Error("offline with no cached shell");
        });
      });
  });
}

self.addEventListener("fetch", function (event) {
  var request = event.request;
  if (request.method !== "GET") return;
  var url = new URL(request.url);
  if (url.origin !== self.location.origin) return;
  if (url.pathname.indexOf(SCOPE) !== 0) return;

  if (request.mode === "navigate") {
    event.respondWith(networkFirstShell(request));
    return;
  }
  if (url.pathname.indexOf(SCOPE + "assets/") === 0 || url.pathname.indexOf(SCOPE + "fonts/") === 0) {
    event.respondWith(cacheFirst(request));
  }
});
